# 40_figures.R: heatmaps and line plots for the sampling-requirement simulation. Palette: petrol #246878, orange #C45C19, sage #79936C, purple #615A83, grey #848B8D, ink #252B2D.
suppressMessages({library(dplyr); library(tidyr); library(ggplot2); library(patchwork)}); T <- "revision_sampling/tables"; FD <- "revision_sampling/figures"; dir.create(FD, FALSE, TRUE)
PET <- "#246878"; ORA <- "#C45C19"; SAG <- "#79936C"; PUR <- "#615A83"; GRY <- "#848B8D"; INK <- "#252B2D"
th <- function(b = 7) theme_minimal(base_size = b) + theme(panel.grid = element_blank(), strip.text = element_text(face = "bold", size = b, colour = INK), axis.text = element_text(colour = INK), axis.title = element_text(colour = INK), plot.title = element_text(face = "bold", size = b + 1, colour = INK), legend.key.size = unit(3, "mm"), plot.tag = element_text(face = "bold", size = 9))
sv <- function(p, name, w, h) for (e in c("pdf", "png", "svg")) ggsave(file.path(FD, sprintf("%s.%s", name, e)), p, width = w, height = h, dpi = 220, device = if (e == "pdf") cairo_pdf else NULL)
rd <- function(f) read.csv(file.path(T, f)); lev_env <- c("uniform", "normal", "clustered"); lev_n <- c(100, 250, 500, 1000, 2500, 5000)
prep <- function(d) { if ("sampler" %in% names(d)) d$sampler <- factor(d$sampler, c("random", "balanced"), c("Random", "Balanced")); d$env <- factor(d$env, lev_env, c("Uniform sites", "Normal sites", "Clustered sites")); if ("n_sites" %in% names(d)) d$n_sites <- factor(d$n_sites, lev_n); if ("order" %in% names(d)) d$order <- factor(d$order, c(2, 3, 5, 10, 20)); d }
# generic heatmap: x = sites (or combinations), y = zeta order, fill = value; blank/hatched cell marker when 'show' is FALSE (e.g. fewer than 3 supported estimates)
hm <- function(d, x, y, fill, lab, title, lim = NULL, cols = c("white", PET), fmt = function(v) sprintf("%.0f", v), facet = sampler ~ env, show = NULL, xlab = "Number of independent sites", ylab = "Zeta order k", na_txt = "–", legend = "") {
  d$.v <- d[[fill]]; d$.show <- if (is.null(show)) !is.na(d$.v) else (!is.na(d$.v) & d[[show]]); d$.lab <- ifelse(d$.show, fmt(d$.v), na_txt); d$.v[!d$.show] <- NA; d$.col <- ifelse(!is.na(d$.v) & !is.null(lim) & d$.v > mean(lim), "w", "d")
  ggplot(d, aes(.data[[x]], .data[[y]], fill = .v)) + geom_tile(colour = "white", linewidth = .4) + geom_text(aes(label = .lab, colour = .col), size = 2.1) + scale_colour_manual(values = c(w = "white", d = INK), guide = "none") +
    scale_fill_gradient(low = cols[1], high = cols[2], limits = lim, na.value = "#EDEEEE", name = legend, oob = scales::squish) + facet_grid(facet) + labs(x = xlab, y = ylab, title = title) + th() + theme(axis.text.x = element_text(size = 5.5)) }
for (SIM in c("meta", "known")) { sfx <- if (SIM == "meta") "metacommunity" else "known_parameter"
  av <- prep(rd(sprintf("sim_%s_availability_sites.csv", SIM))); ac <- prep(rd(sprintf("sim_%s_accuracy_sites.csv", SIM))); pr <- prep(rd(sprintf("sim_%s_prediction_sites.csv", SIM)))
  acB <- ac %>% filter(model == "additive", contrast == "B_LowHigh") %>% mutate(sup3 = n_est >= 3); acB <- left_join(av[, c("env", "sampler", "n_sites", "order")], acB, by = c("env", "sampler", "n_sites", "order")); acB$sup3[is.na(acB$sup3)] <- FALSE; acB$success_dT_all_units[is.na(acB$success_dT_all_units)] <- 0
  p1 <- hm(av %>% mutate(v = 100 * supported_fraction), "n_sites", "order", "v", "", sprintf("Availability of matched position-spread contrasts (%s)", sfx), lim = c(0, 100), legend = "% of replicates\nwith support")
  sv(p1, sprintf("Fig_S1_availability_%s", sfx), 7.2, 4.4)
  p2 <- hm(acB %>% mutate(v = 100 * success_dT_all_units), "n_sites", "order", "v", "", sprintf("Accurate position contrast (B, Low to High; unsupported = failure; %s)", sfx), lim = c(0, 100), cols = c("white", SAG), legend = "% of all\nreplicates")
  sv(p2, sprintf("Fig_S2_success_position_contrast_%s", sfx), 7.2, 4.4)
  p3 <- hm(acB %>% mutate(v = median_abs_err_dT), "n_sites", "order", "v", "", sprintf("Median absolute error of the position contrast (pp; supported replicates, n >= 3; %s)", sfx), lim = c(0, max(5, quantile(acB$median_abs_err_dT[acB$sup3], .95, na.rm = TRUE))), cols = c("white", ORA), fmt = function(v) sprintf("%.1f", v), show = "sup3", legend = "pp")
  sv(p3, sprintf("Fig_S3_error_position_contrast_%s", sfx), 7.2, 4.4)
  acA <- ac %>% filter(model == "additive", contrast == "A_Intermediate") %>% mutate(sup3 = n_est >= 3); acA <- left_join(av[, c("env", "sampler", "n_sites", "order")], acA, by = c("env", "sampler", "n_sites", "order")); acA$sup3[is.na(acA$sup3)] <- FALSE
  p3b <- hm(acA %>% mutate(v = median_abs_err_dT), "n_sites", "order", "v", "", sprintf("Median absolute error of the spread contrast at the intermediate position (pp; n >= 3; %s)", sfx), lim = c(0, max(2, quantile(acA$median_abs_err_dT[acA$sup3], .95, na.rm = TRUE))), cols = c("white", PUR), fmt = function(v) sprintf("%.1f", v), show = "sup3", legend = "pp")
  sv(p3b, sprintf("Fig_S3b_error_spread_contrast_%s", sfx), 7.2, 4.4)
  p4a <- hm(pr %>% mutate(v = skill_additive), "n_sites", "order", "v", "", sprintf("Held-out skill of total dissimilarity, additive MS-GDUM (1 - MSE / Var of test response; %s)", sfx), lim = c(0, 1), cols = c("white", PET), fmt = function(v) sprintf("%.2f", v), legend = "skill")
  p4b <- hm(pr %>% mutate(v = skill_gain_median), "n_sites", "order", "v", "", "Gain in held-out skill over spread-only MS-GDM (additive - spread-only)", lim = c(-.05, .25), cols = c("white", ORA), fmt = function(v) sprintf("%.2f", v), legend = "skill gain")
  sv(p4a / p4b + plot_layout(guides = "keep"), sprintf("Fig_S4_prediction_%s", sfx), 7.2, 8.4)
  # sites vs combinations
  avC <- prep(rd(sprintf("sim_%s_availability_combinations.csv", SIM))); avC$n_combos_target <- factor(avC$n_combos_target); avF <- prep(rd(sprintf("sim_%s_availability_factorial_k5.csv", SIM))); avF$n_combos_target <- factor(avF$n_combos_target)
  line_av <- function(d, x, ttl, xl) ggplot(d, aes(.data[[x]], 100 * supported_fraction, colour = order, group = order)) + geom_line(linewidth = .5) + geom_point(size = 1.1) + facet_grid(sampler ~ env) + scale_colour_manual(values = c(PET, SAG, PUR, ORA, GRY), name = "Order k") + labs(x = xl, y = "% replicates with support", title = ttl) + th() + theme(axis.text.x = element_text(size = 5.5))
  pa <- line_av(av, "n_sites", "More independent sites (4,000 combinations)", "Number of sites"); pb <- line_av(avC, "n_combos_target", "More combinations (500 sites)", "Number of sampled combinations")
  sv(pa / pb + plot_layout(guides = "collect"), sprintf("Fig_S5_sites_vs_combinations_%s", sfx), 7.2, 7.6)
  acF <- prep(rd(sprintf("sim_%s_accuracy_factorial_k5.csv", SIM))) %>% filter(model == "additive", contrast == "B_LowHigh"); acF$n_combos_target <- factor(acF$n_combos_target); acF <- left_join(avF[, c("env", "sampler", "n_sites", "n_combos_target", "supported_fraction")], acF, by = c("env", "sampler", "n_sites", "n_combos_target")); acF$success_dT_all_units[is.na(acF$success_dT_all_units)] <- 0
  pf1 <- hm(avF %>% mutate(v = 100 * supported_fraction), "n_sites", "n_combos_target", "v", "", sprintf("Availability at order 5: sites x combinations (%s)", sfx), lim = c(0, 100), ylab = "Number of sampled combinations", legend = "% support")
  pf2 <- hm(acF %>% mutate(v = 100 * success_dT_all_units), "n_sites", "n_combos_target", "v", "", "Accurate position contrast at order 5 (% of all replicates)", lim = c(0, 100), cols = c("white", SAG), ylab = "Number of sampled combinations", legend = "% accurate")
  sv(pf1 / pf2, sprintf("Fig_S6_factorial_order5_%s", sfx), 7.2, 8.2)
  # paired balanced vs random
  pp <- rd(sprintf("sim_%s_paired_availability.csv", SIM)); pp <- pp %>% mutate(diff = 100 * (balanced_supported - random_supported)); pp$order <- factor(pp$order, c(2, 3, 5, 10, 20)); pp$n_sites <- factor(pp$n_sites, lev_n); pp$env <- factor(pp$env, lev_env, c("Uniform sites", "Normal sites", "Clustered sites"))
  p7 <- ggplot(pp, aes(n_sites, order, fill = diff)) + geom_tile(colour = "white", linewidth = .4) + geom_text(aes(label = sprintf("%+.0f", diff)), size = 2.1, colour = INK) + scale_fill_gradient2(low = ORA, mid = "white", high = PET, midpoint = 0, limits = c(-100, 100), name = "pp change in\n% support") + facet_wrap(~env, nrow = 1) + labs(x = "Number of independent sites", y = "Zeta order k", title = sprintf("Balanced minus random combination sampling: availability, same sites and number of combinations (%s)", sfx)) + th() + theme(axis.text.x = element_text(size = 5.5))
  sv(p7, sprintf("Fig_S7_balanced_minus_random_%s", sfx), 7.2, 2.6) }
cat("figures written\n")
